// Code demostration for the workshop - Introduction to Creative Coding: Interactive Fireworks Party
// Tutorial created by Echo Hui

let fireworks = [];
let fireworksImg;

function preload() {
	fireworksImg = loadImage("https://openprocessing.org/sketch/1539861/files/___");
}

function setup() {
	createCanvas(windowWidth, windowHeight);
	background(0);
	fill(0);
	rect(0, 0, width, height);
	noStroke();

	// fireworks = new Particle({
	// 	pos: createVector(random(width), random(height)),
	// });
}

function draw() {
	fill(0, 8); // background with opacity
	rect(0, 0, width, height);

	// add a new firework
	if (random(1) < 0.01) { // around 5% chance of adding a new firework
		 fireworks.push(new Firework({}));
	}

	// show the firework
	for (let i = fireworks.length - 1; i >= 0; i--) {
		fireworks[i].show();
		// remove extra fireworks
		if (fireworks[i].done()) {
			fireworks.splice(i, 1);
		}
	}
}

// === Tab: particle ===
// Individual particle
class Particle {
	constructor(args) {
		let def = {
			pos: createVector(0, 0),
			vel: createVector(0, -10),
			acc: createVector(0, 0),
			gForce: createVector(0, 0.1), // gravitational force
			r: random(2,6),
			hue: 360,
			seed: true,
			lifespan: 1,
			color: color('#ffffff'),
			endColor: color('#ffffff'),
		};
		Object.assign(def,args);
		Object.assign(this,def);
	}

	applyForce() {
		this.acc.add(this.gForce); // F = ma, here it simplies to F = a * 1
	}

	update() {
		this.vel.add(this.acc);
		this.pos.add(this.vel);
		this.acc.mult(0); // clears out the acceleration
	}

	show() {
		// displays the particle
		push();
			colorMode(HSB);
			translate(this.pos.x, this.pos.y);
			if (this.seed) {
				fill(this.color);
			} else {
				this.lifespan -= 0.005;
				fill(this.hue, 100, 100, this.lifespan);
			}
			circle(0,0,this.r);
		pop();

	}

	done() { 
		// check if the particle is faded out
		return this.lifespan <= 0 ? true : false;
	}
}

// === Tab: firework ===
// contains a particle, and the explosion of particles
class Firework {
	constructor(args) {
		var def = {
			// initialize each Firework class with a particle
			// firework: new Particle({
			// 						pos: createVector(random(width), random(height)),
			// 					}),

			firework: new EmojiParticle({
									pos: createVector(random(width), random(height - (height / 10), height)), // createVector(random(width), random(height)),
									r: random(30, 35),
								}),
			// array for storing explosion of particles
			particles: [], 
			particlesCount: 0,
			explodeStatus: false,
		};
		Object.assign(def,args);
		Object.assign(this,def);
	}

	// check if the particle reaches the highest point
	checkExplodePoint() {
		if (this.firework.vel.y >=0) {
			this.explodeStatus = true;
			this.explode();
		}
	}

	explode() {
		let baseHue = 180;
		this.particlesCount = random(30, 60);

		for( let i = 0; i < this.particlesCount; i++){
			let hue = random(0,120);
			// let objParticle = new Particle({
			let objParticle = new EmojiParticle({
				pos: createVector(this.firework.pos.x, this.firework.pos.y),
				vel: p5.Vector.random2D().mult(random(2, 5)),
				r: random(this.firework.r / 2, this.firework.r),
				hue: baseHue + hue,
				seed: false,
			})
			this.particles.push(objParticle)
		}
	}

	show() {
		push();
			colorMode(HSB);

			this.firework.applyForce();
			this.firework.update();

			// show the seed particle until it reaches the highest point
			if (!this.explodeStatus) {
				this.checkExplodePoint();
				this.firework.show();
			}

			// display fireworks explosion
			// for (let i = 0; i < this.particles.length; i++) {
			for (let i = this.particles.length - 1; i >= 0; i--) {
				this.particles[i].applyForce();
				this.particles[i].update();
				this.particles[i].show();

				// remove extra particles when it's faded out
				if (this.particles[i].done()) {
					this.particles.splice(i, 1);
				}
			}
		pop();
	}

	done() { 
		// check if the particle exceeds the browser window
		return this.explodeStatus && this.particles.length === 0 ? true : false;
	}
}

// === Tab: emojiParticle ===
// Particle System Inheritance
class EmojiParticle extends Particle {
  constructor(pos, r) {
    super(pos, r);
  }

  show() {
    push();
			this.lifespan -= 0.005;
			imageMode(CENTER);
    	image(fireworksImg, this.pos.x, this.pos.y, this.r, this.r);
    pop();
  }
}

